main-breadcrumbs.source:
{% assign background_rgb = section.settings.background_color | color_to_rgb %}
{% assign text_rgb = section.settings.text_color | color_to_rgb %}

<style>
  [data-section-id="{{ section.id }}"]{

    {% if background_rgb != 'rgba(0, 0, 0, 0.0)' %}
      --color-custom-background: {{ section.settings.background_color }};
    {% endif %}

    {% if text_rgb != 'rgba(0, 0, 0, 0.0)' %}
      --color-custom-text: {{ section.settings.text_color }};
      --color-links: {{ section.settings.text_color }};
    {% endif %}

    {% if section.settings.margin-top %}
        --section-gap-top: {{ section.settings.margin-top }}px;
    {% endif %}

    {% if section.settings.margin-bottom %}
        --section-gap-bottom: {{ section.settings.margin-bottom }}px;
    {% endif %}
  }
</style>
<div class="breadcrumbs__wrapper" data-section-id="{{ section.id }}">
  <div class="breadcrumbs {% if section.settings.full-width-enabled %}breadcrumbs--full-width{% endif %}">
    <ul class="breadcrumbs__list">
      <li class="breadcrumbs__item">
        <a href="{{ routes.root_url }}" class="breadcrumbs__link">{{ shop.name | default: 'CALQIX' }}</a>
      </li>
      <li class="breadcrumbs__item">
        {% if collection.url %}
          {{ collection.title | link_to: collection.url }}
        {% else %}
          {{ product.collections[0].title | link_to: product.collections[0].url, class: 'breadcrumbs__link' }}
        {% endif %}
      </li>
      {% if product %}
        <li class="breadcrumbs__item">
          {{ product.title }}
        </li>
      {% endif %}
      {% if page %}
        <li class="breadcrumbs__item">
          {{ page.title | link_to: page.url }}
        </li>
      {% endif %}
    </ul>
  </div>
</div>

{% schema %}
{
  "name": "t:sections.main-breadcrumbs.name",
  "tag": "section",
  "class": "section",
  "settings": [
    {
      "type": "paragraph",
      "content": "t:sections.main-breadcrumbs.settings.paragraph.content"
    },
    {
      "type": "checkbox",
      "id": "full-width-enabled",
      "label": "t:sections.settings.settings.section-full-width.label",
      "info": "t:sections.main-breadcrumbs.settings.full-width-enabled.info",
      "default": false
    },
    {
      "type": "header",
      "content": "t:sections.global.colors",
      "info": "t:sections.global.colors-info"
    },
    {
      "type": "color",
      "id": "text_color",
      "default": "transparent",
      "label": "t:sections.settings.settings.text-color.label"
    },
    {
      "type": "color",
      "id": "background_color",
      "default": "transparent",
      "label": "t:sections.settings.settings.background-color.label"
    },
    {
      "type": "header",
      "content": "t:sections.global.section_spacing"
    },
    {
      "type": "range",
      "id": "margin-top",
      "min": 0,
      "max": 100,
      "unit": "px",
      "step": 4,
      "default": 8,
      "label": "t:sections.settings.settings.distance-top.label"
    },
    {
      "type": "range",
      "id": "margin-bottom",
      "min": 0,
      "max": 100,
      "unit": "px",
      "step": 4,
      "default": 8,
      "label": "t:sections.settings.settings.distance-bottom.label",
      "info": "t:sections.settings.settings.distance-bottom.info"
    }
  ],
  "disabled_on": {
    "groups": ["header", "footer"]
  }
}
{% endschema %}

main-product.source:
{{ 'photoswipe.css' | asset_url | stylesheet_tag }}
{{ 'module-product-gallery.css' | asset_url | stylesheet_tag }}
{{ 'calqix-mobile-thumbs.css' | asset_url | stylesheet_tag }}

{% assign background_rgb = section.settings.background_color | color_to_rgb %}
{% assign text_rgb = section.settings.text_color | color_to_rgb %}
{% assign cq_lang = request.locale.iso_code | downcase | slice: 0, 2 %}
{% assign cq_flowcore_handles = 'calqix-flowcore,flowcore-white,flowcore-green,flowcore-pink' | split: ',' %}
{% assign cq_is_flowcore = false %}
{% if product != blank and cq_flowcore_handles contains product.handle %}
  {% assign cq_is_flowcore = true %}
{% endif %}
{% assign cq_is_translated_flowcore = false %}
{% if cq_is_flowcore %}
  {% case cq_lang %}
    {% when 'nl', 'de', 'fr', 'sv', 'nb', 'da', 'fi' %}
      {% assign cq_is_translated_flowcore = true %}
  {% endcase %}
{% endif %}
{% assign cq_is_oralbiome = false %}
{% if product != blank and product.template_suffix == 'oralbiome' %}
  {% assign cq_is_oralbiome = true %}
{% elsif product != blank and product.handle contains 'oralbiome' %}
  {% assign cq_is_oralbiome = true %}
{% elsif product != blank and product.title contains 'OralBiome' %}
  {% assign cq_is_oralbiome = true %}
{% elsif template contains 'oralbiome' %}
  {% assign cq_is_oralbiome = true %}
{% elsif request.path contains 'oralbiome' %}
  {% assign cq_is_oralbiome = true %}
{% endif %}
{% assign cq_is_translated_oralbiome = false %}
{% if cq_is_oralbiome %}
  {% case cq_lang %}
    {% when 'nl', 'de', 'fr', 'sv', 'nb', 'da', 'fi' %}
      {% assign cq_is_translated_oralbiome = true %}
  {% endcase %}
{% endif %}

<style>
  [id="shopify-section-{{ section.id }}"] {
    {% if background_rgb != 'rgba(0, 0, 0, 0.0)' %}
        --color-overlay-rgb: {{ section.settings.background_color | color_to_rgb | remove: 'rgb(' | remove: ')' }};
        --color-overlay-opacity: 1;
        --color-background: {{ section.settings.background_color }};
        --color-border: {{ section.settings.background_color }};
        --color-input-background: {{ section.settings.background_color }};
        --swiper-navigation-color: {{ section.settings.background_color }};
        --color-text-highlight: {{ section.settings.background_color }};
    {% endif %}


    {% if text_rgb != 'rgba(0, 0, 0, 0.0)' %}
        --color-custom-text: {{ section.settings.text_color }};
        --color-body-text: {{ section.settings.text_color }};
        --custom-section-color-border: {{ section.settings.text_color }};
        --color-price: {{ section.settings.text_color }};
        --color-brand: {{ section.settings.text_color }};
        --color-body-text: {{ section.settings.text_color }};
        --color-bullet: {{ section.settings.text_color }};
        --color-links-active: {{ section.settings.text_color }};
        --color-links: {{ section.settings.text_color }};
        --color-input-border: {{ section.settings.text_color }};
        --color-input-text: {{ section.settings.text_color }};
        --color-input-placeholder: {{ section.settings.text_color }};
        --color-body-text: {{ section.settings.text_color }};
        --swiper-theme-color: {{ section.settings.text_color }};

        .wt-slider__container {
          --color-border: {{ section.settings.text_color }};
        }
    {% endif %}

    {% if section.settings.margin-top %}
        --section-gap-top: {{ section.settings.margin-top }}px;
    {% endif %}

    {% if section.settings.margin-bottom %}
        --section-gap-bottom: {{ section.settings.margin-bottom }}px;
    {% endif %}

    {% if section.settings.desktop-image-ratio == 'square' %}
        --aspect-ratio: 1/1;
    {% endif %}
    {% if section.settings.desktop-image-ratio == 'portrait' %}
        --aspect-ratio: var(--aspect-ratio-portait);
    {% endif %}
    {% if section.settings.desktop-image-ratio == 'original' %}
        --aspect-ratio: auto;
    {% endif %}

        .wt-product__img {
          {%- case section.settings.desktop-image-ratio -%}
          {% when 'square'%}
              --aspect-ratio: 1/1;
          {% when 'portrait' %}
              --aspect-ratio: var(--aspect-ratio-portait);
          {% endcase %}
        }
  }

    {%- for block in section.blocks -%}
    {%- case block.type -%}
    {%- when 'title' -%}
    [data-block-id="{{ block.id }}"]
    {
        --font-text-scale-desk:{{ block.settings.size_text | divided_by: 100.0 }};
        --font-text-scale: {{ block.settings.size_text_mobile | divided_by: 100.0 }};
    }
    {%- when 'price' -%}
    {% assign mp_price_font_family = '"DM Serif Display", Georgia, serif' %}
    {% case block.settings.price_font_family %}
      {% when 'theme_price' %}
        {% assign mp_price_font_family = 'var(--font-price)' %}
      {% when 'theme_heading' %}
        {% assign mp_price_font_family = 'var(--font-headline)' %}
      {% when 'theme_body' %}
        {% assign mp_price_font_family = 'var(--font-base)' %}
      {% when 'dm_sans' %}
        {% assign mp_price_font_family = '"DM Sans", sans-serif' %}
    {% endcase %}
    {% if block.settings.price_custom_font_family != blank %}
      {% assign mp_price_font_family = block.settings.price_custom_font_family %}
    {% endif %}
    #price-{{ section.id }} {
        margin-top: {{ block.settings.price_margin_top }}px;
        margin-bottom: {{ block.settings.price_margin_bottom }}px;
    }
    #price-{{ section.id }} .price--main-product-block .wt-product__price__final,
    #price-{{ section.id }} .price--main-product-block .wt-product__price__compare,
    #price-{{ section.id }} .price--main-product-block .variant-item__old-price {
        font-family: {{ mp_price_font_family }};
        font-style: {{ block.settings.price_font_style }};
        font-weight: {{ block.settings.price_font_weight }};
        letter-spacing: {{ block.settings.price_letter_spacing }}px;
        line-height: {{ block.settings.price_line_height | divided_by: 100.0 }};
        text-transform: {{ block.settings.price_text_transform }};
    }
    #price-{{ section.id }} .price--main-product-block .wt-product__price__final {
        font-size: {{ block.settings.price_font_size_mobile }}px !important;
    }
    @media (min-width: 900px) {
      #price-{{ section.id }} .price--main-product-block .wt-product__price__final {
          font-size: {{ block.settings.price_font_size_desktop }}px !important;
      }
    }
    #price-{{ section.id }} .price--main-product-block .price__sale.visible,
    #price-{{ section.id }} .price--main-product-block .price__sale.visible-main-product,
    #price-{{ section.id }} .price--main-product-block .price__sale .price__sale__details-wrapper,
    #price-{{ section.id }} .price--main-product-block .price__sale .price__details {
        gap: {{ block.settings.price_group_gap }}px;
    }
    #price-{{ section.id }} .price--main-product-block.price:not(.price--on-sale) .wt-product__price__final,
    #price-{{ section.id }} .price--main-product-block.price:not(.price--on-sale) .price__regular .price-item--regular {
        color: {{ block.settings.price_regular_color }};
    }
    #price-{{ section.id }} .price--main-product-block.price.price--on-sale .price__sale .wt-product__price__final,
    #price-{{ section.id }} .price--main-product-block.price.price--on-sale .price__sale .price-item--sale {
        color: {{ block.settings.price_sale_color }};
    }
    #price-{{ section.id }} .price--main-product-block .wt-product__price__compare,
    #price-{{ section.id }} .price--main-product-block .variant-item__old-price {
        color: {{ block.settings.price_compare_color }};
        text-decoration-color: {{ block.settings.price_compare_line_color }};
        text-decoration-thickness: {{ block.settings.price_compare_line_thickness }}px;
        opacity: {{ block.settings.price_compare_opacity | divided_by: 100.0 }};
    }
    #price-{{ section.id }} .price--main-product-block .wt-product__price__compare {
        font-size: {{ block.settings.old_price_font_size_mobile }}px !important;
    }
    #price-{{ section.id }} .price--main-product-block .variant-item__old-price {
        font-size: {{ block.settings.old_price_font_size_mobile }}px !important;
    }
    @media (min-width: 900px) {
      #price-{{ section.id }} .price--main-product-block .wt-product__price__compare {
          font-size: {{ block.settings.old_price_font_size_desktop }}px !important;
      }
      #price-{{ section.id }} .price--main-product-block .variant-item__old-price {
          font-size: {{ block.settings.old_price_font_size_desktop }}px !important;
      }
    }
    #price-{{ section.id }} .price--main-product-block .price__sale .price-item--percent {
        color: {{ block.settings.discount_badge_text_color }};
        background: {{ block.settings.discount_badge_background_color }};
        border: {{ block.settings.discount_badge_border_width }}px solid {{ block.settings.discount_badge_border_color }};
        border-radius: {{ block.settings.discount_badge_radius }}px;
        padding: {{ block.settings.discount_badge_padding_vertical }}px {{ block.settings.discount_badge_padding_horizontal }}px;
        font-family: {{ mp_price_font_family }};
        font-size: {{ block.settings.discount_badge_font_size }}px;
        font-style: normal;
        font-weight: {{ block.settings.discount_badge_font_weight }};
        line-height: 1;
    }
    #product-tax-{{ section.id }} {
        color: {{ block.settings.price_note_color }};
        font-size: {{ block.settings.price_note_size_mobile }}px;
        line-height: 1.4;
        margin-top: {{ block.settings.price_note_margin_top }}px;
    }
    @media (min-width: 900px) {
      #product-tax-{{ section.id }} {
          font-size: {{ block.settings.price_note_size }}px;
      }
    }
    {% when 'image' %}
    [data-block-id="{{ block.id }}"] {

    {% if block.settings.margin-top %}
        --block-margin-top: {{ block.settings.margin-top }}px;
    {% endif %}

    {% if block.settings.margin-bottom %}
        --block-margin-bottom: {{ block.settings.margin-bottom }}px;
    {% endif %}

        .featured-icon__title, .featured-icon__text{
            --font-text-scale-desk:{{ block.settings.size_heading | divided_by: 100.0 }};
            --font-text-scale: {{ block.settings.size_heading_mobile | divided_by: 100.0 }};
        }

        .svg-icon {
            --size-icon: {{ block.settings.size_heading_mobile | divided_by: 100.0 }};
            --size-icon-desk: {{ block.settings.size_heading | divided_by: 100.0 }};
        }

    }

    {% when 'separator' %}
    [data-block-id="{{ block.id }}"] .wt-product__separator {
        --section-gap-top: {{ block.settings.margin-top }}px;
        --section-gap-bottom: {{ block.settings.margin-bottom }}px;
    }

    {% when 'complementary' %}
    [data-block-id="{{ block.id }}"] .wt-product__upsell__image {
      {%- case block.settings.image-ratio -%}
      {% when 'square'%}
          --aspect-ratio: 1/1;
      {% when 'portrait' %}
          --aspect-ratio: var(--aspect-ratio-portait);
      {% endcase %}
    }

    {% when 'upsell' %}
    [data-block-id="{{ block.id }}"] .wt-product__upsell__image {
      {%- case block.settings.image-ratio -%}
      {% when 'square'%}
          --aspect-ratio: 1/1;
      {% when 'portrait' %}
          --aspect-ratio: var(--aspect-ratio-portait);
      {% endcase %}
    }

    {% when 'variant_picker' %}
      .wt-product__options {
          {% comment %}--section-gap-top: {{ block.settings.margin-top }}px;{% endcomment %}
          {% comment %}--section-gap-bottom: {{ block.settings.margin-bottom }}px;{% endcomment %}
          {% comment %}{% if block.settings.radius == 'custom' %}{% endcomment %}
          {% comment %}--custom-border-radius: {{ block.settings.border_radius }}px;{% endcomment %}
          {% comment %}{% endif %}{% endcomment %}
          {% comment %}--custom-size: {{ block.settings.thumb_size }}px;{% endcomment %}

      }
      .wt-product__options .f-thumb__list__item {
          {% comment %}height: {{ block.settings.thumb_size }}px;{% endcomment %}
          /*height: var(--custom-size);*/
          /*width: auto;*/
      }

    {% when 'promo' %}
      [data-block-id="{{ block.id }}"] .wt-product__promo{

        {% assign background_rgb = block.settings['background_color'] | color_to_rgb %}
        {% assign text_rgb = block.settings['color-body-text'] | color_to_rgb %}

        {% if background_rgb != 'rgba(0, 0, 0, 0.0)' %}
          --block-color-background: {{ block.settings.background_color }};
        {% endif %}

        {% if text_rgb != 'rgba(0, 0, 0, 0.0)' %}
          --block-color-text: {{ block.settings.color-body-text }};
        {% endif %}

        --block-text-alignment: {{ block.settings.text_alignment }};
        --block-padding-top: {{ block.settings.padding-top }}px;
        --block-padding-bottom: {{ block.settings.padding-bottom }}px;


      }
    {% when 'buy_buttons' %}
      [data-block-id="{{ block.id }}"] {
        {% assign background_rgb = block.settings['background_color'] | color_to_rgb %}
        {% assign text_rgb = block.settings['text_color'] | color_to_rgb %}

        {% if background_rgb != 'rgba(0, 0, 0, 0.0)' %}
          --color-button-primary-background: {{ block.settings.background_color }};
          --color-button-primary-border: {{ block.settings.background_color }};
          --color-button-primary-background-hover: {{ block.settings.background_color  }};

          --color-button-secondary-background: {{ block.settings.background_color }};
          --color-button-secondary-border: {{ block.settings.background_color }};
          --color-button-secondary-background-hover: {{ block.settings.background_color }};

        {% endif %}

        {% if text_rgb != 'rgba(0, 0, 0, 0.0)' %}
          --color-button-primary-text: {{ block.settings.text_color }};
          --color-button-primary-text-hover: {{ block.settings.text_color }};

          --color-button-secondary-text: {{ block.settings.text_color }};
          --color-button-secondary-text-hover: {{ block.settings.text_color }};

        {% endif %}
      }
      [data-block-id="{{ block.id }}"] .wt-product__add-to-cart {
        width: 100%;
      }{% when 'feature_icons' %}
      [data-block-id="{{ block.id }}"]{
        --columns-number-mobile: {{block.settings.items_per_row }};
        --columns-number-desktop: {{block.settings.items_per_row_desktop }};
        --icon-size-mobile: {{block.settings.icon_size_mobile }}px;
        --icon-size-desktop: {{block.settings.icon_size_desktop }}px;
        --font-text-scale-mobile: {{ block.settings.size_text_mobile | divided_by: 100.0 }};
        --font-text-scale-desktop: {{ block.settings.size_text | divided_by: 100.0 }};
      }

    {% when 'payments_badge' %}
      [data-block-id="{{ block.id }}"] {
        --text-align: {{ block.settings.desktop_text_horizontal_position }};

        {% assign background_rgb = block.settings['background_color'] | color_to_rgb %}
        {% assign text_rgb = block.settings['color-body-text'] | color_to_rgb %}

        {% if background_rgb != 'rgba(0, 0, 0, 0.0)' %}
          --block-color-background: {{ block.settings.background_color }};
          --block-padding: 8px;
        {% endif %}

        {% if text_rgb != 'rgba(0, 0, 0, 0.0)' %}
          --block-color-text: {{ block.settings.color-body-text }};
        {% endif %}

        {% case block.settings.desktop_text_horizontal_position %}
          {% when 'left' %}
            --justify-content: flex-start;
          {% when 'center' %}
            --justify-content: center;
          {% when 'right' %}
            --justify-content: flex-end;
        {% endcase %}

      }
    {% when 'feature_tags' %}
      [data-block-id="{{ block.id }}"] {
        {% assign border_rgb = block.settings['border_color'] | color_to_rgb %}
        {% assign text_rgb = block.settings['text_color'] | color_to_rgb %}

        {% if border_rgb != 'rgba(0, 0, 0, 0.0)' %}
          label:before {
            border-color: {{ block.settings.border_color }};
          }
        {% endif %}

        {% if text_rgb != 'rgba(0, 0, 0, 0.0)' %}
            color: {{ block.settings.text_color }};
        {% endif %}
      }
    {% when 'product_variations' %}
      [data-block-id="{{ block.id }}"] {
          --custom-size: {{ block.settings.swatch_size }}px;
        {% if block.settings.radius == 'custom' %}
          --custom-border-radius: {{ block.settings.border_radius }}px;
        {% endif %}
      }
    {% when 'specification' %}
      [data-block-id="{{ block.id }}"]{
        --color-background-odd: {{ block.settings.color-background-odd }};
        --color-text-odd: {{ block.settings.color-text-odd | color_to_rgb | remove: 'rgb(' | remove: ')' }};
        --left-column-opacity: {{ block.settings.color-text-left-opacity | divided_by: 100.0 }};
      }
    {%- endcase -%}
    {%- endfor -%}
</style>

<script src="{{ 'product-form.js' | asset_url }}" defer="defer"></script>
<script src="{{ 'quick-add.js' | asset_url }}" defer="defer"></script>
<script src="{{ 'variants.js' | asset_url }}" defer="defer"></script>
<script src="{{ 'drawer-select.js' | asset_url }}" defer="defer"></script>
<script src="{{ 'model_element.js' | asset_url }}" defer="defer"></script>
<script src="{{ 'variant-dropdown.js' | asset_url }}" defer="defer"></script>

{%- if section.settings.enable_calqix_product_information_style -%}
  {{ 'calqix-product-information.css' | asset_url | stylesheet_tag }}
{%- endif -%}

{% if cq_is_oralbiome %}
  <script>
    (function () {
      function initOralBiomeZoom() {
        var gallery = document.getElementById('MediaGallery-{{ section.id }}');
        if (!gallery) return;
        var images = gallery.querySelectorAll('[data-gallery] .wt-product__img');
        images.forEach(function (image) {
          image.addEventListener('pointermove', function (event) {
            if (event.pointerType === 'touch') return;
            var rect = image.getBoundingClientRect();
            var x = ((event.clientX - rect.left) / rect.width) * 100;
            var y = ((event.clientY - rect.top) / rect.height) * 100;
            image.style.setProperty('--cq-zoom-x', Math.max(0, Math.min(100, x)).toFixed(2) + '%');
            image.style.setProperty('--cq-zoom-y', Math.max(0, Math.min(100, y)).toFixed(2) + '%');
          }, { passive: true });
          image.addEventListener('pointerleave', function () {
            image.style.removeProperty('--cq-zoom-x');
            image.style.removeProperty('--cq-zoom-y');
          }, { passive: true });
        });
      }

      if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initOralBiomeZoom);
      } else {
        initOralBiomeZoom();
      }
    })();
  </script>
{% endif %}

<script>
  (function () {
    function isOralBiomePage() {
      return document.body.classList.contains('template-product-oralbiome') ||
        window.location.pathname.toLowerCase().indexOf('oralbiome') !== -1 ||
        /OralBiome/i.test(document.title || '');
    }

    function bindOralBiomeGallery() {
      if (!isOralBiomePage()) return;
      var gallery = document.querySelector('gallery-section[data-product-page]');
      if (!gallery) return;

      gallery.querySelectorAll('[data-gallery] a[href*="/cdn/shop/files"], [data-gallery] a[href*="cdn/shop/files"]').forEach(function (link) {
        link.addEventListener('click', function (event) {
          event.preventDefault();
        });
        link.removeAttribute('target');
      });

      gallery.querySelectorAll('[data-gallery] .wt-product__img').forEach(function (image) {
        if (image.dataset.cqZoomBound === '1') return;
        image.dataset.cqZoomBound = '1';
        image.addEventListener('pointermove', function (event) {
          if (event.pointerType === 'touch') return;
          var rect = image.getBoundingClientRect();
          var x = ((event.clientX - rect.left) / rect.width) * 100;
          var y = ((event.clientY - rect.top) / rect.height) * 100;
          image.style.setProperty('--cq-zoom-x', Math.max(0, Math.min(100, x)).toFixed(2) + '%');
          image.style.setProperty('--cq-zoom-y', Math.max(0, Math.min(100, y)).toFixed(2) + '%');
        }, { passive: true });
        image.addEventListener('pointerleave', function () {
          image.style.removeProperty('--cq-zoom-x');
          image.style.removeProperty('--cq-zoom-y');
        }, { passive: true });
      });
    }

    function ensureOralBiomeUsps() {
      if (!isOralBiomePage()) return;
      if (document.querySelector('.calqix-obp-usp-fallback')) return;
      var switcher = document.querySelector('.calqix-colour-switcher-block, [id^="ccs-block-"]');
      if (!switcher || !switcher.parentNode) return;
      var items = [
        {
          text: '4 studied oral strains',
          icon: '<path d="M8 30h24M20 30V10M10 10h20" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/><circle cx="12" cy="20" r="5" stroke="currentColor" stroke-width="1.8"/><circle cx="28" cy="20" r="5" stroke="currentColor" stroke-width="1.8"/><path d="M16 20h8" stroke="#9f7d27" stroke-width="1.6" stroke-linecap="round"/>'
        },
        {
          text: 'Fresh breath support',
          icon: '<ellipse cx="20" cy="22" rx="11" ry="6" stroke="currentColor" stroke-width="1.8"/><circle cx="20" cy="20" r="8" stroke="#9f7d27" stroke-width="1.6"/><path d="M20 8v6M20 26v6M8 20h6M26 20h6" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/>'
        },
        {
          text: 'Teeth whitening support',
          icon: '<path d="M26 8a12 12 0 1 0 0 24 9 9 0 0 1 0-24Z" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"/><ellipse cx="14" cy="28" rx="5.5" ry="3.2" stroke="#9f7d27" stroke-width="1.8"/><circle cx="30" cy="14" r="1" fill="currentColor"/>'
        },
        {
          text: '30-day supply per jar',
          icon: '<circle cx="20" cy="20" r="13" stroke="currentColor" stroke-width="1.8"/><circle cx="20" cy="20" r="13" stroke="#9f7d27" stroke-width="1.8" stroke-dasharray="2 4"/><text x="20" y="24" text-anchor="middle" font-family="DM Serif Display, Georgia, serif" font-size="11" fill="currentColor">30</text>'
        }
      ];
      var wrapper = document.createElement('div');
      wrapper.className = 'calqix-obp-usp-fallback calqix-inline-usps';
      wrapper.setAttribute('data-block-id', 'oralbiome-usp-fallback');
      wrapper.innerHTML = '<ul class="calqix-obp-usp-fallback__list" role="list">' + items.map(function (item) {
        return '<li class="calqix-obp-usp-fallback__item"><span class="calqix-obp-usp-fallback__icon" aria-hidden="true"><svg viewBox="0 0 40 40" fill="none" xmlns="http://www.w3.org/2000/svg">' + item.icon + '</svg></span><span class="calqix-obp-usp-fallback__text">' + item.text + '</span></li>';
      }).join('') + '</ul>';
      switcher.parentNode.insertBefore(wrapper, switcher);
    }

    function init() {
      bindOralBiomeGallery();
      ensureOralBiomeUsps();
    }

    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', init);
    } else {
      init();
    }
  })();
</script>

{% assign selected_variant = product.selected_variant %}
{% assign enabled_preselect = false %}
