              {%- endfor -%}
              {%- if ccs_active_name == blank -%}{%- assign ccs_active_name = b.swatch_1_name -%}{%- endif -%}
              {%- if ccs_active_handle == blank and b.swatch_1_product != blank -%}
                {%- assign ccs_active_handle = b.swatch_1_product.handle -%}
              {%- endif -%}
              <div id="ccs-block-{{ block.id }}" class="calqix-colour-switcher-block" {{ block.shopify_attributes }}>
                <div class="ccs-label">
                  {%- if b.show_active_name and ccs_active_name != blank -%}
                    {{ ccs_label_text }}: <span class="ccs-active-name">{{ ccs_active_name }}</span>
                    {%- if ccs_highlight_text != blank and b.highlight_product != blank and ccs_active_handle == b.highlight_product.handle -%}
                      <span class="ccs-chip">{{ ccs_highlight_text }}</span>
                    {%- endif -%}
                  {%- else -%}
                    {{ ccs_label_text }}
                  {%- endif -%}
                </div>
                <div class="ccs-swatches">
                  {%- for i in (1..6) -%}
                    {%- assign ccs_pk  = 'swatch_' | append: i | append: '_product' -%}
                    {%- assign ccs_nk  = 'swatch_' | append: i | append: '_name' -%}
                    {%- assign ccs_bk  = 'swatch_' | append: i | append: '_border' -%}
                    {%- assign ccs_bcl = 'swatch_' | append: i | append: '_border_color' -%}
                    {%- assign ccs_product = b[ccs_pk] -%}
                    {%- if ccs_product != blank -%}
                      {%- assign ccs_resolved_handle = ccs_product.handle -%}
                      {%- if ccs_resolved_handle == blank -%}
                        {%- assign ccs_resolved_handle = ccs_product -%}
                      {%- endif -%}
                      {%- assign ccs_product = all_products[ccs_resolved_handle] -%}
                      {%- if ccs_product == blank and ccs_resolved_handle contains 'calqix-' -%}
                        {%- assign ccs_try_handle = ccs_resolved_handle | remove_first: 'calqix-' -%}
                        {%- assign ccs_product = all_products[ccs_try_handle] -%}
                        {%- if ccs_product != blank -%}{%- assign ccs_resolved_handle = ccs_try_handle -%}{%- endif -%}
                      {%- endif -%}
                      {%- if ccs_product == blank -%}
                        {%- assign ccs_try_handle = 'calqix-' | append: ccs_resolved_handle -%}
                        {%- assign ccs_product = all_products[ccs_try_handle] -%}
                        {%- if ccs_product != blank -%}{%- assign ccs_resolved_handle = ccs_try_handle -%}{%- endif -%}
                      {%- endif -%}
                      {%- assign ccs_display_name = b[ccs_nk] -%}
                      {%- if ccs_display_name == blank and ccs_product != blank -%}
                        {%- assign ccs_display_name = ccs_product.title -%}
                      {%- endif -%}
                      {%- assign ccs_is_active = false -%}
                      {%- if ccs_resolved_handle == product.handle -%}{%- assign ccs_is_active = true -%}{%- endif -%}
                      {%- assign safe_root = routes.root_url | append: '/' | replace: '//', '/' -%}
                      <span class="ccs-swatch-item{% if ccs_is_active %} ccs-swatch-item--active{% endif %}">
                        <a href="{{ safe_root }}products/{{ ccs_resolved_handle }}"
                           class="ccs-swatch {% if ccs_is_active %}ccs-active{% endif %} {% if b[ccs_bk] %}ccs-swatch--bordered{% endif %}"
                           style="{% if b[ccs_bk] %}border-color: {{ b[ccs_bcl] }} !important;{% endif %}"
                           aria-label="{{ ccs_display_name }}" title="{{ ccs_display_name }}">
                          {%- if ccs_product != blank and ccs_product.featured_image != blank -%}
                            {{
                              ccs_product.featured_image
                              | image_url: width: 128
                              | image_tag:
                                class: 'ccs-swatch__img',
                                loading: 'lazy',
                                widths: '48, 64, 96, 128',
                                sizes: '56px',
                                alt: ccs_display_name
                            }}
                          {%- endif -%}
                          <span class="ccs-tooltip">{{ ccs_display_name }}</span>
                        </a>
                        <span class="ccs-swatch-name" aria-hidden="true">{{ ccs_display_name }}</span>
                      </span>
                    {%- endif -%}
                  {%- endfor -%}
                </div>
                {%- if ccs_helper_text != blank -%}
                  <p class="ccs-helper">{{ ccs_helper_text }}</p>
                {%- endif -%}
              </div>
              {%- if b.custom_js != blank -%}
                <script>(function(){var blockId='{{ block.id }}';var section=document.getElementById('ccs-block-'+blockId);{{ b.custom_js }}})()</script>
              {%- endif -%}

            {%- when 'calqix_bundle' -%}
              {%- if product.template_suffix == 'oralbiome' -%}
                {%- render 'calqix-bundle-picker',
                  tier_2_discount: block.settings.tier_2_discount,
                  tier_3_discount: block.settings.tier_3_discount,
                  tier_3_free_jar: block.settings.tier_3_free_jar,
                  popular_tier: block.settings.popular_tier
                -%}
                {%- render 'calqix-subscribe-widget' -%}
                {%- if block.settings.show_flavor_picker -%}
                  {%- render 'calqix-product-flavor-picker' -%}
                {%- endif -%}
              {%- endif -%}

            {%- when 'video_reels' -%}
              {{ 'module-product-video-carousel.css' | asset_url | stylesheet_tag }}
              {{ 'section-shoppable-video.css' | asset_url | stylesheet_tag }}
              <script src="{{ 'video-controls.js' | asset_url }}" defer="defer"></script>
              <script type="module" src="{{ 'module-video-reels.js' | asset_url }}" defer="defer"></script>
              <product-video-reels class="wt-product-video-reels"
                   not-quick-add
                   data-auto-advanced="{{ block.settings.auto_advanced }}"
                   data-show-unmute="{{ block.settings.show_unmute }}"
                   data-show-play-pause="{{ block.settings.show_play_pause }}"
                   data-show-quick-add="{{ block.settings.enable_quick_add }}"
              >
                  <template id="video-reels-arrows">
                      <button class="video-reels-modal__nav video-reels-modal__nav--prev" aria-label="Prev">
                          {% render 'icons', id: 'arrow-left' %}
                      </button>
                      <button class="video-reels-modal__nav video-reels-modal__nav--next" aria-label="Next">
                          {% render 'icons', id: 'arrow-right' %}
                      </button>
                  </template>
                  <template id="video-reels-close-icon">
                      {% render 'icons', id: 'close' %}
                  </template>
                  <template id="video-reels-controls">
                      {% render 'play-pause-button', classname: '' %}
                      <button
                              aria-label="{{ 'aria-label.video-reels-toggle-sound' | t }}"
                              class="wt-video__sound-toggle"
                              data-sound="off"
                      >
                          {% render 'icons', id: 'volume' %}
                          {% render 'icons', id: 'volume-muted' %}
                      </button>
                  </template>


                  {% if block.settings.heading %}
                      <div class="wt-product-video-reels__headline">
                          {{ block.settings.heading }}
                      </div>
                  {% endif %}

                  <script type="module" src="{{ 'slider.js' | asset_url }}" defer="defer"></script>

                  <slideshow-section class="wt-slider wt-product-video-reels__wrapper">
                      <div data-swiper-container class="wt-product-video-reels__container wt-slider__container wt-slider__container--video-carousel">
                          <div data-swiper-container class="video-reels__container">
                              {%- comment -%}
                                Loop through indexes 1..5 and render each video only if it exists
                              {%- endcomment -%}
                              {% for i in (1..6) %}
                                  {%- capture field_name %}video_reels_{{ i }}{% endcapture -%}
                                  {%- capture product_field %}video_reels_{{ i }}_product{% endcapture -%}
                                  {% if block.settings[field_name] != blank %}
                                      <div
                                          data-swiper-slide
                                          data-block-id="{{ block.id }}"
                                          class="wt-product-video-reels__item"
                                      >
                                          <div class="wt-product-video-reels__item__content {% if block.settings.enable_quick_add == false %}wt-product-video-reels__item__content--disable-quick-add{% endif %}">
                                              <low-power-video>
                                                  {{ block.settings[field_name]
                                                  | video_tag: autoplay: false, loop: true, muted: true, controls: false, image_size: '600x'
                                                  }}
                                              </low-power-video>

                                              <div class="wt-product-video-reels__play-icon">
                                                  {% render 'icon-play' %}
                                              </div>

                                              {%- assign selected_product = block.settings[product_field] -%}
                                              {% if selected_product != null %}
                                                  {% render 'shoppable-product-card',
                                                      product: selected_product,
                                                      hide_brand: block.settings.hide_brand
                                                  %}
                                              {% endif %}
                                          </div>
                                      </div>
                                  {% endif %}
                              {% endfor %}
                          </div>
                      </div>

                      {%- comment -%}
                        Navigation arrows for horizontal scrolling (w razie potrzeby)
                      {%- endcomment -%}
                      <div class="wt-product-video-reels__nav wt-product-video-reels__nav--prev">
                          <button class="wt-product-video-reels__nav__btn wt-product-video-reels__nav__btn--prev" aria-label="Scroll Left">
                              {% render 'icons', id: 'arrow-left' %}
                          </button>
                      </div>
                      <div class="wt-product-video-reels__nav wt-product-video-reels__nav--next">
                          <button class="wt-product-video-reels__nav__btn wt-product-video-reels__nav__btn--next" aria-label="Scroll Right">
                              {% render 'icons', id: 'arrow-right' %}
                          </button>
                      </div>

                      {% comment %}<button class="wt-product-video-reels__nav wt-product-video-reels__nav--next" aria-label="Scroll Right">›</button>{% endcomment %}

                    {%liquid
                        assign video_reels_desktop_spv = 4.5
                        if section.settings.desktop-media-size == 'normal'
                            assign video_reels_desktop_spv = 5
                        endif
                    %}


                      <script data-swiper-configuration type="text/json">
                          {
                            "slidesPerView": 2.5,
                            "slidesPerGroup": 2,
                            "spaceBetween": 8,
                            "freeMode": false,
                            "speed": 150,
                            "grabCursor": false,
                            "centeredSlides": false,
                            "loop": false,
                            "slideToClickedSlide": true,
                            "enableOnMedia": "(min-width: 0px)",
                            "breakpoints": {
                              "600": {
                                "slidesPerView": 3.5,
                                "slidesPerGroup": 3
                              },
                              "1200": {
                                "slidesPerView": {{ video_reels_desktop_spv }},
                                "slidesPerGroup": 5
                              }
                            },
                            "pagination": false,
                            "navigation": {
                              "nextEl": ".wt-product-video-reels__nav--next",
                              "prevEl": ".wt-product-video-reels__nav--prev"
                            }
                          }
                      </script>
                  </slideshow-section>

              </product-video-reels>
            {%- when 'feature_icons' -%}
              {% liquid
                assign icons_list = null
                assign uploaded_icons = null

                assign metafield = block.settings.metafield | strip | split: '.'
                assign metafield_namespace = metafield | first | strip
                assign metafield_key = metafield | last | strip
                assign feature_icons = product.metafields[metafield_namespace][metafield_key]

                if feature_icons.type == 'list.metaobject_reference' and feature_icons.value.count > 0
                  assign icons_list = feature_icons.value
                endif

                if block.settings.icon_1_image != null or block.settings.icon_2_image != null or block.settings.icon_3_image != null or block.settings.icon_4_image != null
                  assign uploaded_icons = true
                endif
              %}

              {% if icons_list or uploaded_icons %}
                <div
                  class="wt-product__feature-icons {% if settings.animations %} scroll-trigger animate--slide-in {% endif %} {% if settings.disabled_animations_on_mobile %} disabled-on-mobile {% endif %}"
                  data-block-id="{{ block.id }}"
                  not-quick-add
                >
                  <ul
                    class="
                      wt-product__feature-icons__list
                      {% if block.settings.layout_select == 'row' %}
                       wt-product__feature-icons__list--row
                       {% elsif block.settings.layout_select == 'row-left' %}
                        wt-product__feature-icons__list--row-left
                      {% endif %}
                    "
                  >
                    {% if block.settings.icon_1_image != null %}
                      <li
                        class="
                          wt-product__feature-icons__item
                          {% if block.settings.layout_select == 'column' %} wt-product__feature-icons__item--row {% endif %}
                        "
                      >
                        {{
                          block.settings.icon_1_image
                          | image_url: width: block.settings.icon_1_image.width
                          | image_tag: alt: icon.label
                        }}

                        {%- if block.settings.icon_1_text != blank and block.settings.show_icons_label -%}
                          <label class="wt-product__feature-icons__label" for="{{ block.settings.icon_1_text  }}">
                            {{- block.settings.icon_1_text -}}
                          </label>
                        {%- endif -%}
                      </li>
                    {% endif %}

                    {% if block.settings.icon_2_image != null %}
                      <li
                        class="
                          wt-product__feature-icons__item
                          {% if block.settings.layout_select == 'column' %} wt-product__feature-icons__item--row {% endif %}
                        "
                      >
                        {{
                          block.settings.icon_2_image
                          | image_url: width: block.settings.icon_2_image.width
                          | image_tag: alt: icon.label
                        }}

                        {%- if block.settings.icon_2_text != blank and block.settings.show_icons_label -%}
                          <label class="wt-product__feature-icons__label" for="{{ block.settings.icon_2_text  }}">
                            {{- block.settings.icon_2_text -}}
                          </label>
                        {%- endif -%}
                      </li>
                    {% endif %}

                    {% if block.settings.icon_3_image != null %}
                      <li
                        class="
                          wt-product__feature-icons__item
                          {% if block.settings.layout_select == 'column' %} wt-product__feature-icons__item--row {% endif %}
                        "
                      >
                        {{
                          block.settings.icon_3_image
                          | image_url: width: block.settings.icon_3_image.width
                          | image_tag: alt: icon.label
                        }}

                        {%- if block.settings.icon_3_text != blank and block.settings.show_icons_label -%}
                          <label class="wt-product__feature-icons__label" for="{{ block.settings.icon_3_text  }}">
                            {{- block.settings.icon_3_text -}}
                          </label>
                        {%- endif -%}
                      </li>
                    {% endif %}

                    {% if block.settings.icon_4_image != null %}
                      <li
                        class="
                          wt-product__feature-icons__item
                          {% if block.settings.layout_select == 'column' %} wt-product__feature-icons__item--row {% endif %}
                        "
                      >
                        {{
                          block.settings.icon_4_image
                          | image_url: width: block.settings.icon_4_image.width
                          | image_tag: alt: icon.label
                        }}

                        {%- if block.settings.icon_4_text != blank and block.settings.show_icons_label -%}
                          <label class="wt-product__feature-icons__label" for="{{ block.settings.icon_4_text  }}">
                            {{- block.settings.icon_4_text -}}
                          </label>
                        {%- endif -%}
                      </li>
                    {% endif %}

                    {% for icon in icons_list %}
                      <li
                        class="
                          wt-product__feature-icons__item
                          {% if block.settings.layout_select == 'column' %} wt-product__feature-icons__item--row {% endif %}
                        "
                      >
                        {%- if icon.image -%}
                          {{ icon.image | image_url: width: icon.image.width | image_tag: alt: icon.label }}
                        {%- endif -%}
                        {%- if icon.label != blank and block.settings.show_icons_label -%}
                          <label class="wt-product__feature-icons__label" for="{{ icon.label }}">
                            {{- icon.label -}}
                          </label>
                        {%- endif -%}
                      </li>
                    {% endfor %}
                  </ul>
                </div>
              {% endif %}

            {% when 'payments_badge' %}
              {%- assign cq_pb_content = block.settings.content -%}
              {%- if cq_is_translated_flowcore -%}
                {%- assign cq_pb_content = 'calqix_flowcore.main.payments_badge_content' | t -%}
              {%- endif -%}
              <div
                data-block-id="{{ block.id }}"
                class=" {% if settings.animations %} scroll-trigger animate--slide-in {% endif %} {% if settings.disabled_animations_on_mobile %} disabled-on-mobile {% endif %}"
              >
                <div class="wt-product__payments-badge">
                  <div class="wt-product__payments-badge__content">
                    {{ cq_pb_content }}
                  </div>

                  <div class="wt-product__payments-badge__icons">
                    {% if block.settings.badge_type == 'payment_icons' %}
                      {%- assign cq_payment_methods = 'ideal_wero,klarna,credit_card,paypal,eps,belfius,kbc_cbc,twint,swish' | split: ',' -%}
                      <ul class="wt-product__payments-badge__icons__list" role="list">
                        {%- for cq_method in cq_payment_methods -%}
                          {%- liquid
                            case cq_method
                              when 'ideal_wero'
                                assign cq_method_label = 'iDEAL / Wero'
                              when 'klarna'
                                assign cq_method_label = 'Klarna'
                              when 'credit_card'
                                assign cq_method_label = 'Credit card'
                              when 'paypal'
                                assign cq_method_label = 'PayPal'
                              when 'eps'
                                assign cq_method_label = 'EPS'
                              when 'belfius'
                                assign cq_method_label = 'Belfius'
                              when 'kbc_cbc'
                                assign cq_method_label = 'KBC/CBC'
                              when 'twint'
                                assign cq_method_label = 'TWINT'
                              when 'swish'
                                assign cq_method_label = 'Swish'
                            endcase
                          -%}
                          <li class="wt-product__payments-badge__icons__item wt-product__payments-badge__icons__item--{{ cq_method | replace: '_', '-' }}" title="{{ cq_method_label }}" aria-label="{{ cq_method_label }}">
                            {%- case cq_method -%}
                              {%- when 'ideal_wero' -%}
                                <span class="wt-product__payments-badge__logo-set wt-product__payments-badge__logo-set--ideal-wero" aria-hidden="true">
                                  {{ 'ideal' | payment_type_svg_tag: class: 'icon icon--full-color' }}
                                  <img src="{{ 'WERO.png' | file_url }}" alt="" loading="lazy" class="wt-product__payments-badge__custom-logo">
                                </span>
                              {%- when 'klarna' -%}
                                {{ 'klarna' | payment_type_svg_tag: class: 'icon icon--full-color' }}
                              {%- when 'paypal' -%}
                                {{ 'paypal' | payment_type_svg_tag: class: 'icon icon--full-color' }}
                              {%- when 'credit_card' -%}
                                <span class="wt-product__payments-badge__logo-set wt-product__payments-badge__logo-set--cards" aria-hidden="true">
                                  {{ 'visa' | payment_type_svg_tag: class: 'icon icon--full-color' }}
                                  {{ 'master' | payment_type_svg_tag: class: 'icon icon--full-color' }}
                                  {{ 'maestro' | payment_type_svg_tag: class: 'icon icon--full-color' }}
                                </span>
                              {%- when 'eps' -%}
                                {{ 'eps' | payment_type_svg_tag: class: 'icon icon--full-color' }}
                              {%- when 'belfius' -%}
                                {{ 'belfius' | payment_type_svg_tag: class: 'icon icon--full-color' }}
                              {%- when 'kbc_cbc' -%}
                                <span class="wt-product__payments-badge__mini-logo wt-product__payments-badge__mini-logo--kbc" aria-hidden="true">KBC</span>
                              {%- when 'twint' -%}
                                {{ 'twint' | payment_type_svg_tag: class: 'icon icon--full-color' }}
                              {%- when 'swish' -%}
                                {{ 'swish' | payment_type_svg_tag: class: 'icon icon--full-color' }}
                              {%- else -%}
                                <span class="wt-product__payments-badge__method-label" aria-hidden="true">{{ cq_method_label }}</span>
                            {%- endcase -%}
                          </li>
                        {%- endfor -%}
                      </ul>
                    {% else %}
                      {% render 'picture',
                        desktop_image: block.settings.desktop_image,
                        mobile_image: block.settings.mobile_image
                      %}
                    {% endif %}
                  </div>
                </div>
              </div>
            {% when 'specification' %}
              <collapsible-section
                class="wt-collapse wt-collapse--always {% if settings.animations %} scroll-trigger animate--slide-in {% endif %} {% if settings.disabled_animations_on_mobile %} disabled-on-mobile {% endif %}"
                data-toggle-tabindex="button, [href], input, select"
                not-quick-add
              >
                <div
                  role="button"
                  tabindex="0"
                  class="wt-collapse__trigger{% if block.settings.is_open %} wt-collapse__trigger--active{% endif %}"
                  {% if block.settings.is_open %}
                    data-open="true"
                  {% endif %}
                  aria-expanded="{% if block.settings.is_open %}true{% else %}false{% endif %}"
                  aria-controls="Specification-{{ block.id }}"
                >
                  <div class="wt-collapse__trigger__text">
                    {% if block.settings.icon != 'none' %}
                      <div class="wt-collapse__trigger__icon">
                        {% render 'icon-accordion', icon: block.settings.icon %}
                      </div>
                    {% endif %}
                    <div class="wt-collapse__trigger__title">{{ block.settings.heading }}</div>
                  </div>
                  <div class="wt-icon" aria-hidden="true">
                    {% render 'icons', id: 'plus' %}
                  </div>
                </div>
                <div class="wt-collapse__target" data-block-id="{{ block.id }}" id="Specification-{{ block.id }}">
                  <div class="wt-collapse__target--text rte">
                    <div class="wt-product__spec">
                      {% assign metafield = block.settings.metafield | strip | split: '.' %}
                      {% assign metafield_namespace = metafield | first | strip %}
                      {% assign metafield_key = metafield | last | strip %}
                      {% assign specification = product.metafields[metafield_namespace][metafield_key]  | newline_to_br %}
                      {% assign text = specification | strip_newlines %}
                      {% assign table_rows = text | split: '<br /><br />' %}
                      {% for row in table_rows %}
                      <div class="wt-product__spec__row">
                        {% assign row_cells= row | split: '<br />' %}
                        {% for cell in row_cells limit: 1 %}
                            <div class="wt-product__spec__cell wt-product__spec__cell--title"><p>{{ cell }}</p></div>
                        {% endfor %}
                        <div class="wt-product__spec__cell">
                          {% for cell in row_cells offset: 1 %}
                              <p>{{ cell }}</p>
                          {% endfor %}
                        </div>
                      </div>
                      {% endfor %}
                    </div>
                  </div>
                </div>
              </collapsible-section>
          {%- endcase -%}
        {%- endfor -%}
      </div>
    </section>

    {% if section.settings.enable_sticky_buy_button %}
      {%- comment -%}
        Sticky Add-to-Cart (mobile)
        - Row 1: product title + price (price mirrors `#price-{section.id}` via
                 MutationObserver in assets/pdp.js -> StickyBuyButton, so it
                 reflects variant, subscription, and flavor/bundle changes
                 automatically across all locales).
        - Row 2: quantity stepper (proxies +/- to the main `.js-counter-*`
                 buttons so a single quantity source of truth stays in the
                 main ATC form) + CTA with bag icon.
        - Row 3: trust micro-line (unchanged).
      {%- endcomment -%}
      <sticky-buy-button class="wt-product__sticky-buy"
        data-section-id="{{ section.id }}"
        data-product-form-id="{{ product_form_id }}"
        {% if product.has_only_default_variant and product.available %}data-add-to-cart{% endif %}
      >
        <div class="cq-sticky__inner">
          <div class="cq-sticky__info">
            <span class="cq-sticky__title">{{ product.title }}</span>
          </div>
        </div>

        <div class="cq-sticky__action">
          {%- comment -%} Qty stepper intentionally removed — sticky shows title + synced price + full-width CTA. {%- endcomment -%}
          <div class="cq-sticky__qty" data-cq-sticky-qty hidden>
            <button type="button"
              class="cq-sticky__qty-btn cq-sticky__qty-btn--dec"
              aria-label="{{ 'aria-label.component-counter-counter-decrease' | t }}"
              data-cq-sticky-qty-dec>
              <svg width="14" height="14" viewBox="0 0 14 14" fill="none" aria-hidden="true">
                <path d="M3 7h8" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/>
              </svg>
            </button>
            <input type="text"
              class="cq-sticky__qty-input"
              value="1"
              min="1"
              max="999"
              inputmode="numeric"
              pattern="[0-9]*"
              aria-label="{{ 'aria-label.component-counter-counter-quantity' | t }}"
              data-cq-sticky-qty-input>
            <button type="button"
              class="cq-sticky__qty-btn cq-sticky__qty-btn--inc"
              aria-label="{{ 'aria-label.component-counter-counter-increase' | t }}"
              data-cq-sticky-qty-inc>
              <svg width="14" height="14" viewBox="0 0 14 14" fill="none" aria-hidden="true">
                <path d="M7 3v8M3 7h8" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/>
              </svg>
            </button>
          </div>

          <button
            aria-label="{{ 'products.product.add_to_cart' | t }}"
            class="js-add-to-cart wt-product__sticky-buy__button cq-sticky__cta"
            {% if product.has_only_default_variant and product.available %}
              type="submit"
              form="{{product_form_id}}"
            {% endif %}
          >
            <span class="cq-sticky__cta-icon" aria-hidden="true">{% render 'icons', id: 'bag' %}</span>
            <span class="cq-sticky__cta-text">
            {% if product.has_only_default_variant and product.available %}
                {{ 'products.product.add_to_cart' | t }}
              {% elsif product.available == false %}
                {{ 'products.product.sold_out' | t }}
              {% elsif product.options.size == 1 %}
                {{ 'products.product.choose_option' | t }}
              {% else %}
                {{ 'products.product.choose_options' | t }}
              {% endif%}
            </span>
            <span class="cq-sticky__cta-sep" aria-hidden="true">·</span>
            <span class="cq-sticky__cta-price" data-cq-sticky-price-slot>
              <span class="cq-sticky__amount">{{ product.selected_or_first_available_variant.price | money }}</span>
            </span>
          </button>
        </div>
        <div class="cq-sticky__trust">
          {%- if cq_is_flowcore -%}
            ✓ {{ 'calqix_flowcore.main.trust_badge_1' | t }} · {{ 'calqix_flowcore.main.trust_badge_3' | t }}
          {%- elsif cq_is_oralbiome -%}
            ✓ {{ 'calqix_oralbiome.main.trust_1' | t }} · {{ 'calqix_oralbiome.main.trust_3' | t }}
          {%- else -%}
            {%- case cq_lang -%}
              {%- when 'nl' -%}✓ Gratis verzending vanaf €30 · 30 dagen retour
              {%- when 'de' -%}✓ Kostenloser Versand ab €30 · 30 Tage Ruckgabe
              {%- when 'fr' -%}✓ Livraison gratuite des €30 · Retour sous 30 jours
              {%- when 'sv' -%}✓ Fri frakt fran 300 kr · 30 dagars retur
              {%- when 'nb' -%}✓ Gratis frakt fra 300 kr · 30 dagers retur
              {%- when 'da' -%}✓ Gratis fragt fra 250 kr · 30 dages retur
              {%- when 'fi' -%}✓ Ilmainen toimitus yli 30 € · 30 paivan palautus
              {%- else -%}✓ Free shipping from €30 · 30-day returns
            {%- endcase -%}
          {%- endif -%}
        </div>
      </sticky-buy-button>
    {% endif %}

  </div>
</section>

